import React, { useContext, useEffect, useState } from "react";
import Navbar from "../Home/Navbar";
import { Link } from "react-router";
import { ApiValue } from "../Data/AllData";
import { CartProvider, useCart } from "react-use-cart";

function Page() {


  const {addItem} = useCart();



  const Api = useContext(ApiValue);

  const [Search, setSearh] = useState(0);

  const getValue = (event) => {
    setSearh(event.target.value);
  };








  return (
    <div>
      <div className="container">
        <div className="row">
          <div className="col-md-10 m-auto">
            <input
              onChange={getValue}
              className="form-control"
              placeholder="Search"
            ></input>
          </div>

          {Api.map((item) => {
            return Search == 0 ? (
              <div className="col-md-4 text-center mb-4">
                <img src={item.images[0]} className="w-100"></img>
                <h4>{item.title}</h4>
                <h6>price: {item.price}$</h6>
                <h6>ID: {item.id}</h6>
                <Link
                  to={`/singleproduct/${item.id}`}
                  className="btn btn-dark btn-block"
                >
                  Details
                </Link>
                <button onClick={()=>addItem(item)} className="btn btn-success btn-block" >Add to cart</button>

              </div>
            ) : item.id == Search ? (
              <div className="col-md-4 text-center mb-4">
                <img src={item.images[0]} className="w-100"></img>
                <h4>{item.title}</h4>
                <h6>price: {item.price}$</h6>
                <h6>ID: {item.id}</h6>
                <Link
                  to={`/singleproduct/${item.id}`}
                  className="btn btn-dark btn-block"
                >
                  Details
                </Link>
                <button onClick={()=>addItem(item)} className="btn btn-success btn-block" >Add to cart</button>
              </div>
            ) : item.title.toUpperCase().includes(Search.toUpperCase()) ? (
              <div className="col-md-4 text-center mb-4">
                <img src={item.images[0]} className="w-100"></img>
                <h4>{item.title}</h4>
                <h6>price: {item.price}$</h6>
                <h6>ID: {item.id}</h6>
                <Link
                  to={`/singleproduct/${item.id}`}
                  className="btn btn-dark btn-block"
                >
                  Details
                </Link>
                <button onClick={()=>addItem(item)} className="btn btn-success btn-block" >Add to cart</button>

              </div>
            ) : null;
          })}
        </div>
      </div>
    </div>
  );
}




