import React, { useEffect, useState } from "react";
import Navbar from "../Home/Navbar";
import { useParams } from "react-router";
import axios from "axios";
import { CartProvider } from "react-use-cart";

function AllSingleProduct() {
  
  const [ text, setText ] = useState([]);
  const { id } = useParams();
  
  useEffect(() => {
    axios.get(`https://dummyjson.com/products/${id}`).then((element) => {
      setText(element.data);
    });
  },[]);
  
  return (
    <CartProvider>
      <Navbar />
      <br></br>
      <br></br>
      <br></br>
      <br></br>

      <div className="container">

            <div className="row">
              <div className="col-md-6 text-center">
                <img src={text.images} className="w-75"></img>
              </div>
             
              <div className="col-md-6 text-center mt-5 pt-5">
                <h2>{text.title}</h2>
                <h4>{text.brand}</h4>
                <h4>{text.category}</h4>
                <h4>{text.stock}</h4>
              </div>
            </div>
   
      
      </div>
    </CartProvider>
  );
}

export default AllSingleProduct;
