import React from "react";
import Navbar from "../Home/Navbar";
import { CartProvider, useCart } from "react-use-cart";
import { Link } from "react-router";


function Cart() {

    

const {items,totalUniqueItems,updateItemQuantity,removeItem,totalItems,cartTotal,emptyCart,isEmpty} = useCart();
 
if(isEmpty){
    return(
        <div className="text-center">
            <img src="/img/cart.png"></img>
            <h2>Your Cart is empty..</h2>


        </div>
    )
}



 return(

    <div>

        <div className="container">
            <div className="row">
                <div className="col-md-10 m-auto">

                  <ul>
                  
                   {totalUniqueItems==1?(
                        <h4 className="text-center"><span className="badge rounded-pill bg-success text-white px-3 py-2  ">{totalUniqueItems}</span> Item    
                         <button onClick={()=>{emptyCart()}} className="btn btn-danger ml-3">Empty Card</button>
                        </h4>
                        
                    )
                    :(<h4 className="text-center"><span className="badge rounded-pill bg-success text-white px-3 py-2">{totalUniqueItems}</span> Items
                       <button onClick={()=>{emptyCart()}} className="btn btn-danger ml-3">Empty Card</button>
                      </h4>)
                    }

                   

                   
                  </ul>

                    <table className="table table-dark text-center">
                        <thead>
                            <tr>
                                <th>Image</th>
                                <th>name</th>
                                <th>Quantity</th>
                                <th>Price</th>
                                <th>Opreation</th>
                            </tr>
                        </thead>
                    
                        <tbody>
                            {items.map((element)=>{
                                return(
                                    <tr>
                                        <td><img src={element.images[0]} style= {{width:"70px"}}></img></td>
                                        <td>{element.title}</td>
                                        <td>{element.quantity}</td>
                                        <td>{Math.ceil(element.price*element.quantity)}$</td>
                                        <td>
                                            <button onClick={()=>{updateItemQuantity(element.id,element.quantity-1)}} className="btn btn-warning ">-</button>
                                            <button onClick={()=>{updateItemQuantity(element.id,element.quantity+1)}} className="btn btn-success mx-4 ">+</button>
                                            <button className="btn btn-danger" onClick={()=>{removeItem(element.id)}}>&times;</button>
                                        </td>
                                                 
                                    </tr>
                                )
                            
                            })}

                        </tbody>
                    </table>

                    <h2 className="d-inline mx-4">Total quantity</h2> 
                    <h4 className="d-inline badge rounded-pill bg-success text-white px-3 py-2  ">{totalItems}</h4>
                    <br></br>
                    <br></br>
                    <h2 className="d-inline mx-4">Total Price</h2> 
                    <h4 className="d-inline badge rounded-pill bg-primary text-white px-3 py-2  ">{Math.ceil(cartTotal)}$</h4>
                    <br></br>
                    <br></br>
                    <Link to="/AllProducts" className='btn btn-outline-info  btn-block'>Continue Shooping</Link>
                    <Link to="/AllProducts" className='btn btn-outline-success  btn-block'>Payment</Link>
                </div>
            </div>
        </div>



  </div>
)
}





function AllCart() {
  return (
    <CartProvider>
      <Navbar />
      <br></br>
      <br></br>
      <br></br>
      <br></br>
      <Cart/>
    </CartProvider>
  );
}

export default AllCart;
